function Button({ children, variant = "primary", onClick, className = "", type = "button", disabled }) {
  const styles = {
    primary: { background: C.coral, color: "#fff" },
    secondary: { background: "transparent", color: C.ink, border: `1.5px solid ${C.ink}` },
    ghost: { background: "transparent", color: C.blue },
    dark: { background: C.ink, color: "#fff" },
  };
  return (
    <button
      type={type}
      onClick={onClick}
      disabled={disabled}
      className={`px-5 py-2.5 rounded-md text-sm font-semibold transition-transform active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed ${className}`}
      style={{ ...styles[variant], ...body }}
    >
      {children}
    </button>
  );
}

function Field({ label, children }) {
  return (
    <label className="block mb-4">
      <span className="block text-xs font-semibold mb-1.5" style={{ color: C.mist, ...body }}>{label}</span>
      {children}
    </label>
  );
}

const inputStyle = {
  ...body,
  width: "100%",
  padding: "10px 12px",
  borderRadius: 8,
  border: `1.5px solid ${C.line}`,
  outline: "none",
  fontSize: 14,
  color: C.ink,
  background: "#fff",
};

function TextInput(props) {
  return <input {...props} style={{ ...inputStyle, ...(props.style || {}) }} />;
}
function TextArea(props) {
  return <textarea {...props} style={{ ...inputStyle, resize: "vertical", ...(props.style || {}) }} />;
}

/* ---------------------------------- NAVBAR ---------------------------------- */
function NavBar({ page, go, currentUser, onLogout }) {
  const [open, setOpen] = useState(false);
  const links = [
    { id: "home", label: "Home" },
    { id: "about", label: "About" },
  ];
  return (
    <header className="sticky top-0 z-40 border-b" style={{ background: "rgba(238,240,248,0.92)", backdropFilter: "blur(8px)", borderColor: C.line }}>
      <div className="max-w-6xl mx-auto px-5 md:px-8 h-16 flex items-center justify-between">
        <button onClick={() => go(currentUser ? "dashboard" : "home")}><Logo /></button>
        <nav className="hidden md:flex items-center gap-8">
          {links.map(l => (
            <button key={l.id} onClick={() => go(l.id)}
              className="text-sm font-medium"
              style={{ ...body, color: page === l.id ? C.ink : C.mist }}>
              {l.label}
            </button>
          ))}
        </nav>
        <div className="hidden md:flex items-center gap-3">
          {currentUser ? (
            <>
              <span className="text-sm" style={{ ...body, color: C.mist }}>Hi, {currentUser.name?.split(" ")[0] || "there"}</span>
              <Button variant="secondary" onClick={() => go("dashboard")}>Dashboard</Button>
              <button onClick={onLogout} className="text-sm font-semibold" style={{ ...body, color: C.ink }}>Log out</button>
            </>
          ) : (
            <>
              <button onClick={() => go("signin")} className="text-sm font-semibold" style={{ ...body, color: C.ink }}>Sign in</button>
              <Button onClick={() => go("signup")}>Create your card</Button>
            </>
          )}
        </div>
        <button className="md:hidden" onClick={() => setOpen(!open)}>{open ? <X size={22} /> : <Menu size={22} />}</button>
      </div>
      {open && (
        <div className="md:hidden px-5 pb-4 flex flex-col gap-3" style={{ background: C.fog }}>
          {links.map(l => (
            <button key={l.id} onClick={() => { go(l.id); setOpen(false); }} className="text-left text-sm font-medium py-1" style={body}>{l.label}</button>
          ))}
          {currentUser ? (
            <>
              <button onClick={() => { go("dashboard"); setOpen(false); }} className="text-left text-sm font-semibold py-1" style={body}>Dashboard</button>
              <button onClick={() => { onLogout(); setOpen(false); }} className="text-left text-sm font-semibold py-1" style={body}>Log out</button>
            </>
          ) : (
            <>
              <button onClick={() => { go("signin"); setOpen(false); }} className="text-left text-sm font-semibold py-1" style={body}>Sign in</button>
              <Button onClick={() => { go("signup"); setOpen(false); }} className="w-full">Create your card</Button>
            </>
          )}
        </div>
      )}
    </header>
  );
}

