/* ---------------------------------- PUBLIC CARD PAGE ---------------------------------- */
// This is what someone actually lands on when they scan the QR code or tap the NFC card.
function buildVCard(card) {
  const nameParts = (card.name || "").trim().split(/\s+/).filter(Boolean);
  const first = nameParts[0] || "";
  const last = nameParts.slice(1).join(" ");
  const lines = [
    "BEGIN:VCARD",
    "VERSION:3.0",
    `N:${last};${first};;;`,
    `FN:${card.name || ""}`,
  ];
  if (card.company) lines.push(`ORG:${card.company}`);
  if (card.title) lines.push(`TITLE:${card.title}`);
  (card.phones || []).filter(Boolean).forEach(p => lines.push(`TEL;TYPE=CELL:${p}`));
  (card.emails || []).filter(Boolean).forEach(e => lines.push(`EMAIL:${e}`));
  if (card.website) lines.push(`URL:${card.website}`);
  lines.push("END:VCARD");
  return lines.join("\r\n"); // most contact apps require CRLF, not plain \n
}

function downloadVCard(card) {
  const blob = new Blob([buildVCard(card)], { type: "text/vcard" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${(card.name || "contact").replace(/\s+/g, "_")}.vcf`;
  a.click();
  URL.revokeObjectURL(url);
}

function ScanLoader() {
  return (
    <div className="min-h-screen flex flex-col items-center justify-center" style={{ background: C.ink }}>
      <img src={LOGO_ICON} alt="" className="w-16 h-16 rounded-xl object-cover mb-4" />
      <span className="text-2xl font-bold tracking-tight text-white mb-2" style={display}>CardNova</span>
      <p className="text-sm" style={{ ...body, color: "#8A8F98" }}>Opening profile…</p>
    </div>
  );
}

function PublicCardPage({ slug }) {
  const [phase, setPhase] = useState("loading"); // loading | reveal | needsCode | error
  const [card, setCard] = useState(null);
  const [error, setError] = useState("");
  const [codeInput, setCodeInput] = useState("");
  const [leadForm, setLeadForm] = useState({ name: "", email: "", phone: "", message: "" });
  const [leadSent, setLeadSent] = useState(false);
  const [leadError, setLeadError] = useState("");

  const params = new URLSearchParams(window.location.search);
  const linkToken = params.get("link") || undefined;

  const load = async (code) => {
    const minWait = new Promise(r => setTimeout(r, 1400)); // loader shows for at least this long
    try {
      const [data] = await Promise.all([api.getPublicCard(slug, { code, link: linkToken }), minWait]);
      setCard(fromServerCard(data));
      setPhase("reveal");
    } catch (err) {
      await minWait;
      if (err.data?.private) setPhase("needsCode");
      else { setError(err.message); setPhase("error"); }
    }
  };

  useEffect(() => { load(); }, [slug]);

  const submitLead = async (e) => {
    e.preventDefault();
    setLeadError("");
    try {
      await api.submitLead(slug, leadForm);
      setLeadSent(true);
    } catch (err) {
      setLeadError(err.message);
    }
  };

  if (phase === "loading") return <ScanLoader />;

  if (phase === "needsCode") {
    return (
      <div className="min-h-screen flex items-center justify-center px-5" style={{ background: C.fogDeep }}>
        <div className="w-full max-w-sm p-8 rounded-2xl" style={{ background: "#fff", border: `1px solid ${C.line}` }}>
          <Lock size={20} color={C.ink} className="mb-3" />
          <h1 className="mb-1" style={{ ...display, fontSize: 20, fontWeight: 600, color: C.ink }}>This profile is private</h1>
          <p className="text-sm mb-5" style={{ ...body, color: C.mist }}>Enter the access code shared with you to view it.</p>
          <form onSubmit={(e) => { e.preventDefault(); setPhase("loading"); load(codeInput); }}>
            <TextInput value={codeInput} onChange={e => setCodeInput(e.target.value)} placeholder="Access code" className="mb-3" />
            <Button type="submit" className="w-full">Unlock profile</Button>
          </form>
        </div>
      </div>
    );
  }

  if (phase === "error") {
    return (
      <div className="min-h-screen flex items-center justify-center px-5 text-center" style={{ background: C.fogDeep }}>
        <div>
          <p className="text-sm mb-1" style={{ ...display, fontSize: 18, color: C.ink }}>Profile not found</p>
          <p className="text-sm" style={{ ...body, color: C.mist }}>{error}</p>
        </div>
      </div>
    );
  }

  // phase === "reveal"
  const tkPage = resolveDesign(card);
  const phones = (card.phones || []).filter(Boolean);
  const emails = (card.emails || []).filter(Boolean);

  // Real, clickable buttons — styled by the same design engine used in the wizard preview
  const publicActions = (tk) => {
    const css = buttonCss(tk);
    const out = [];
    if (card.buttons.includes("save")) out.push(<button key="save" type="button" onClick={() => downloadVCard(card)} style={css}>Save contact</button>);
    if (card.buttons.includes("call") && phones[0]) out.push(<a key="call" href={`tel:${phones[0]}`} style={css}>Call</a>);
    if (card.buttons.includes("whatsapp") && card.socials?.whatsapp) out.push(<a key="wa" href={`https://wa.me/${card.socials.whatsapp.replace(/\D/g, "")}`} target="_blank" rel="noreferrer" style={css}>WhatsApp</a>);
    if (card.buttons.includes("email") && emails[0]) out.push(<a key="mail" href={`mailto:${emails[0]}`} style={css}>Email</a>);
    if (card.buttons.includes("website") && card.website) out.push(<a key="web" href={card.website.startsWith("http") ? card.website : `https://${card.website}`} target="_blank" rel="noreferrer" style={css}>Visit website</a>);
    if (card.pdf) out.push(<a key="pdf" href={card.pdf} target="_blank" rel="noreferrer" style={{ ...css, background: "transparent", border: "none", color: tk.accent, textDecoration: "underline" }}>View attached PDF</a>);
    return out;
  };

  return (
    <div className="min-h-screen" style={{ background: C.fogDeep }}>
      <div className="max-w-md mx-auto pb-16 min-h-screen" style={{ background: tkPage.bgCss }}>
        <div style={{ fontSize: "min(5vw, 22.4px)" }}>
          <CardView card={card} actions={publicActions} bare />
        </div>

        {(phones.length > 0 || emails.length > 0) && (
          <div className="mx-5 p-4 rounded-xl text-sm" style={{ background: "#fff", border: `1px solid ${C.line}`, ...body }}>
            {phones.map((p, i) => <div key={i} style={{ color: C.ink }}>{p}</div>)}
            {emails.map((e, i) => <div key={i} style={{ color: C.mist }}>{e}</div>)}
          </div>
        )}

        {card.leadCapture?.enabled && (
          <div className="mx-5 mt-4 p-5 rounded-xl" style={{ background: "#fff", border: `1px solid ${C.line}` }}>
            {leadSent ? (
              <p className="text-sm text-center" style={{ ...body, color: C.success }}>Thanks — your details were sent!</p>
            ) : (
              <form onSubmit={submitLead}>
                <p className="text-sm font-semibold mb-3" style={{ ...body, color: C.ink }}>Get in touch</p>
                <ErrorBanner message={leadError} />
                {card.leadCapture.fields.includes("name") && <Field label="Name"><TextInput value={leadForm.name} onChange={e => setLeadForm(f => ({ ...f, name: e.target.value }))} /></Field>}
                {card.leadCapture.fields.includes("email") && <Field label="Email"><TextInput type="email" value={leadForm.email} onChange={e => setLeadForm(f => ({ ...f, email: e.target.value }))} /></Field>}
                {card.leadCapture.fields.includes("phone") && <Field label="Phone"><TextInput value={leadForm.phone} onChange={e => setLeadForm(f => ({ ...f, phone: e.target.value }))} /></Field>}
                {card.leadCapture.fields.includes("message") && <Field label="Message"><TextArea rows={3} value={leadForm.message} onChange={e => setLeadForm(f => ({ ...f, message: e.target.value }))} /></Field>}
                <Button type="submit" className="w-full">Send</Button>
              </form>
            )}
          </div>
        )}

        <p className="text-center text-xs mt-6" style={{ ...body, color: tkPage.fg, opacity: 0.6 }}>Made with CardNova</p>
      </div>
    </div>
  );
}

/* ---------------------------------- APP ROOT ---------------------------------- */
export default function App() {
  const [page, setPage] = useState("home");
  const [loading, setLoading] = useState(true);
  const [cards, setCards] = useState([]);
  const [leads] = useState(seedLeads);
  const [dashTab, setDashTab] = useState("cards");
  const [editingId, setEditingId] = useState(null);
  const [token, setToken] = useState(null);
  const [currentUser, setCurrentUser] = useState(null);

  useEffect(() => {
    const t = setTimeout(() => setLoading(false), 900);
    return () => clearTimeout(t);
  }, []);

  const go = (p) => {
    setLoading(true);
    setTimeout(() => { setPage(p); setLoading(false); window.scrollTo(0, 0); }, 500);
  };

  // Called by SignUpPage/SignInPage once the backend confirms the account is real.
  const onAuthSuccess = (newToken, user) => {
    setToken(newToken);
    setCurrentUser(user);
    setPage("dashboard");
    setDashTab("cards");
  };

  const onLogout = () => {
    setToken(null);
    setCurrentUser(null);
    setCards([]);
    go("home");
  };

  // Called after a successful M-Pesa payment so the plan/cardLimit shown
  // everywhere (sidebar, My Cards, Billing) reflects the upgrade immediately.
  const onUpgraded = async () => {
    try {
      const { user } = await api.me(token);
      setCurrentUser(user);
    } catch (err) {
      // non-critical — the plan change still happened server-side even if this refetch fails
    }
  };

  // A URL like localhost:5173/david (what someone lands on from a QR scan or NFC
  // tap) isn't one of the app's known internal pages, so treat it as a public card.
  const pathname = window.location.pathname.replace(/^\/+/, "");
  const KNOWN_PAGES = ["", "home", "about", "signup", "signin", "dashboard"];
  // /p/your-link is a public menu or QR page made in the "Menus & QR" studio
  if (/^p\/[^/]+\/?$/.test(pathname)) {
    return <StudioPublic slug={decodeURIComponent(pathname.slice(2).replace(/\/$/, ""))} />;
  }
  if (pathname && !KNOWN_PAGES.includes(pathname)) {
    return <PublicCardPage slug={pathname} />;
  }

  return (
    <div style={{ ...body, background: C.fog, minHeight: "100vh" }}>
      {loading && <PageLoader />}
      {page !== "dashboard" && <NavBar page={page} go={go} currentUser={currentUser} onLogout={onLogout} />}
      {page === "home" && <HomePage go={go} />}
      {page === "about" && <AboutPage go={go} />}
      {page === "signup" && <SignUpPage go={go} onAuthSuccess={onAuthSuccess} />}
      {page === "signin" && <SignInPage go={go} onAuthSuccess={onAuthSuccess} />}
      {page === "dashboard" && (
        <>
          <NavBar page={page} go={go} currentUser={currentUser} onLogout={onLogout} />
          <Dashboard
            cards={cards} setCards={setCards} leads={leads}
            tab={dashTab} setTab={setDashTab}
            editingId={editingId} setEditingId={setEditingId}
            go={go} token={token} currentUser={currentUser} onLogout={onLogout} onUpgraded={onUpgraded}
          />
        </>
      )}
    </div>
  );
}
